function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.receipt}</svg>`}
function paintIcons(root=document){$$('[data-icon]',root).forEach(el=>{el.innerHTML=icon(el.dataset.icon)})}

const state={token:localStorage.getItem('ks_token')||'',me:null,items:[],parties:[],accounts:[],dashboard:null,activity:[],saleCart:[],purchaseCart:[],returnCart:[],saleType:'credit',purchaseType:'credit',returnKind:'sale_return',txTab:'all',registerType:'',deferredPrompt:null};

function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`toast show${error?' error':''}`;setTimeout(()=>t.className='toast',3000)}
function queue(){try{return JSON.parse(localStorage.getItem('ks_queue')||'[]')}catch{return[]}}
function saveQueue(q){localStorage.setItem('ks_queue',JSON.stringify(q));updateSyncUI()}
async function api(path,options={}){
  const headers={...(options.headers||{})}; if(state.token)headers.Authorization=`Bearer ${state.token}`;
  if(options.body && !(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=typeof options.body==='string'?options.body:JSON.stringify(options.body)}
  try{const r=await fetch(path,{...options,headers});const data=r.status===204?null:await r.json().catch(()=>null);if(r.status===401){logoutLocal();throw new Error('Login expired')}if(!r.ok)throw new Error(data?.detail||`Request failed (${r.status})`);return data}
  catch(e){if(options.queueable && !navigator.onLine){const q=queue();q.push({path,method:options.method||'POST',body:JSON.parse(options.body),created_at:new Date().toISOString()});saveQueue(q);return {offline:true}}throw e}
}
async function flushQueue(){if(!navigator.onLine||!state.token)return;const q=queue(),left=[];for(const row of q){try{await api(row.path,{method:row.method,body:row.body})}catch{left.push(row)}}saveQueue(left);if(q.length&&!left.length){toast('Offline entries synced');await refreshAll()}}
function updateSyncUI(){const online=navigator.onLine;$('#sync-dot').style.background=online?'var(--green)':'var(--amber)';$('#sync-text').textContent=online?'Online & synced':'Offline mode';$('#queue-text').textContent=queue().length?`${queue().length} pending changes`:'No pending changes';$('#settings-connection').textContent=online?'Online':'Offline';$('#settings-queue').textContent=`${queue().length} pending`}

async function boot(){paintIcons();attachEvents();updateSyncUI();try{const status=await api('/api/setup/status');if(!status.setup_complete)showAuth('setup');else if(!state.token)showAuth('login');else await enterApp()}catch(e){toast(e.message,true)}}
function showAuth(mode){$('#app-shell').classList.add('hidden');$('#auth-screen').classList.remove('hidden');$('#setup-box').classList.toggle('hidden',mode!=='setup');$('#login-box').classList.toggle('hidden',mode!=='login')}
async function enterApp(){state.me=await api('/api/me');$('#auth-screen').classList.add('hidden');$('#app-shell').classList.remove('hidden');$('#shop-name').textContent=state.me.business.name;$('#drawer-shop').textContent=state.me.business.name;$('#profile-btn').textContent=(state.me.business.owner_name||state.me.business.name||'A')[0].toUpperCase();fillBusinessForm();await refreshAll();const requested=new URLSearchParams(location.search).get('page');navigate(requested&&$(`#page-${requested}`)?requested:'home');flushQueue()}
function logoutLocal(){state.token='';localStorage.removeItem('ks_token');state.me=null;showAuth('login')}
async function refreshAll(){await Promise.all([refreshMasterData(),loadDashboard(),loadActivity()]);renderItems();renderParties();renderActivity()}
async function refreshMasterData(){[state.items,state.parties,state.accounts]=await Promise.all([api('/api/items'),api('/api/parties'),api('/api/accounts')]);fillPartySelects();fillEntrySelects()}

function navigate(page){$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${page}`));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.go===page));document.body.classList.toggle('sale-focus',page==='sale');document.body.classList.toggle('purchase-focus',page==='purchase');document.body.classList.toggle('return-focus',page==='return');document.body.classList.toggle('billing-focus',['sale','purchase','return'].includes(page));closeDrawer();window.scrollTo({top:0,behavior:'instant'});if(page==='dashboard')loadDashboard();if(page==='home')loadActivity();if(page==='items')renderItems();if(page==='parties')renderParties();if(page==='transactions')loadTransactions();if(page==='reports')loadReports();if(page==='import')loadImportHistory();if(page==='settings')fillBusinessForm();if(page==='sale'){if($('#sale-firm-name'))$('#sale-firm-name').textContent=state.me?.business?.name||'Kirana Software';$('#sale-time').textContent=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});updateSaleDueDate();updateSalePartyDetails();renderCart('sale')}if(page==='purchase'){if($('#purchase-firm-name'))$('#purchase-firm-name').textContent=state.me?.business?.name||'Kirana Software';$('#purchase-time').textContent=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});updatePurchasePartyDetails();renderCart('purchase')}if(page==='return'){fillReturnPartySelect();updateReturnPartyDetails();renderCart('return')}}
function openDrawer(){$('#side-drawer').classList.add('open');$('#drawer-backdrop').classList.remove('hidden')}
function closeDrawer(){$('#side-drawer').classList.remove('open');$('#drawer-backdrop').classList.add('hidden')}
function closeIfOpen(dialog){if(dialog?.open)dialog.close()}

async function loadDashboard(){state.dashboard=await api('/api/dashboard');const d=state.dashboard;$('#dash-receivable').textContent=money(d.receivable);$('#dash-payable').textContent=money(d.payable);$('#dash-month-sale').textContent=money(d.sales_month);$('#dash-purchases').textContent=money(d.purchases_month);$('#dash-expenses').textContent=money(d.expenses_month);$('#dash-bank').textContent=money(d.bank_balance);$('#dash-cash').textContent=money(d.cash_balance);$('#dash-stock-value').textContent=money(d.stock_value);$('#dash-item-count').textContent=d.item_count;$('#dash-open-count').textContent=d.open_documents?.count||0;$('#dash-open-amount').textContent=money(d.open_documents?.amount);renderChart(d.sales_trend||[]);$('#account-preview').innerHTML=(d.accounts||[]).slice(0,4).map(a=>`<div class="simple-row"><div><b>${esc(a.name)}</b><small>${esc(a.account_type)}</small></div><strong class="${a.balance>=0?'positive':'negative'}">${money(a.balance)}</strong></div>`).join('')||emptyText('No account');$('#low-stock-preview').innerHTML=(d.low_items||[]).map(i=>`<div class="simple-row"><div><b>${esc(i.name)}</b><small>Minimum ${i.min_stock} ${esc(i.unit)}</small></div><strong class="negative">${i.stock}</strong></div>`).join('')||emptyText('No low stock item')}
function renderChart(rows){const el=$('#sales-chart');if(!rows.length){el.innerHTML=emptyText('No sale data');return}const max=Math.max(...rows.map(r=>num(r.amount)),1),w=600,h=190,p=24;const pts=rows.map((r,i)=>({x:p+i*((w-2*p)/Math.max(rows.length-1,1)),y:h-p-(num(r.amount)/max)*(h-2*p),...r}));const line=pts.map(p=>`${p.x},${p.y}`).join(' ');el.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#0b7bc1" stop-opacity=".25"/><stop offset="1" stop-color="#0b7bc1" stop-opacity="0"/></linearGradient></defs><path d="M${pts[0].x},${h-p} L${line.replaceAll(' ', ' L')} L${pts.at(-1).x},${h-p} Z" fill="url(#area)"/><polyline points="${line}" fill="none" stroke="#0b7bc1" stroke-width="4"/><g>${pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="5" fill="#fff" stroke="#0b7bc1" stroke-width="3"/><text x="${p.x}" y="${h-3}" text-anchor="middle" font-size="12" fill="#838999">${p.month}</text>`).join('')}</g></svg>`}

async function loadActivity(){state.activity=await api('/api/activity?limit=100');renderActivity()}
function activityLabel(k){return ({sale:'SALE',purchase:'PURCHASE',expense:'EXPENSE',cash_in:'PAYMENT-IN',cash_out:'PAYMENT-OUT',transfer:'P2P TRANSFER',sale_return:'SALE RETURN',purchase_return:'PURCHASE RETURN',delivery_challan:'DELIVERY CHALLAN',estimate:'ESTIMATE',proforma:'PROFORMA',sale_order:'SALE ORDER',purchase_order:'PURCHASE ORDER',cheque_received:'CHEQUE RECEIVED',cheque_paid:'CHEQUE PAID',loan_in:'LOAN IN',loan_out:'LOAN OUT',asset_purchase:'ASSET PURCHASE',asset_sale:'ASSET SALE'}[k]||k.replaceAll('_',' ').toUpperCase())}
function statusClass(k){return k==='purchase'?'purchase':(k==='expense'||k==='cash_out'?'expense':(['sale','cash_in'].includes(k)?'':'document'))}
function renderActivity(){const q=($('#activity-search')?.value||'').toLowerCase();const rows=state.activity.filter(x=>`${x.title} ${x.ref} ${x.kind}`.toLowerCase().includes(q));$('#activity-list').innerHTML=rows.map(r=>`<article class="transaction-card" data-activity-kind="${r.kind}" data-activity-id="${r.id}"><div class="transaction-top"><div><h3>${esc(r.title||r.ref||activityLabel(r.kind))}</h3><span class="status-pill ${statusClass(r.kind)}">${activityLabel(r.kind)}${num(r.due)>0?' : UNPAID':''}</span></div><time>${niceDate(r.entry_date)}<br><small>${esc(r.ref||'')}</small></time></div><div class="transaction-values"><div><small>Total</small><strong>${money(r.amount)}</strong></div><div><small>${num(r.due)>0?'Balance':'Status'}</small><strong class="${num(r.due)>0?'negative':''}">${num(r.due)>0?money(r.due):esc(r.status||'Completed')}</strong></div><div class="transaction-actions"><span>${icon('receipt')}</span><span>${icon('arrow')}</span></div></div></article>`).join('')||emptyText('Abhi koi transaction nahi hai.')}

function renderItems(){
  if(!$('#items-cards'))return;

  const q=($('#item-filter').value||'').trim().toLowerCase();
  const low=$('#low-stock-btn').classList.contains('active-filter');

  const rows=state.items.filter(i=>{
    const searchable=`${i.name} ${i.sku} ${i.barcode} ${i.category} ${i.size||''} ${i.unit||''}`.toLowerCase();
    return (!q||searchable.includes(q))&&(!low||num(i.stock)<=num(i.min_stock));
  });

  const groups=new Map();

  rows.forEach(item=>{
    const key=String(item.name||'').trim().toLowerCase();

    if(!groups.has(key)){
      groups.set(key,{
        name:item.name,
        variants:[]
      });
    }

    groups.get(key).variants.push(item);
  });

  const grouped=[...groups.values()].sort((a,b)=>
    String(a.name).localeCompare(String(b.name),'en',{sensitivity:'base'})
  );

  $('#items-cards').innerHTML=grouped.map(group=>{
    const variants=group.variants.sort((a,b)=>{
      const av=parseFloat(a.size);
      const bv=parseFloat(b.size);

      if(Number.isFinite(av)&&Number.isFinite(bv))return av-bv;
      return String(a.size||'').localeCompare(String(b.size||''));
    });

    const allLow=variants.every(i=>num(i.stock)<=num(i.min_stock));
    const variantText=variants.length===1?'1 variant':`${variants.length} variants`;

    return `
      <article class="item-card variant-group ${allLow?'low':''}">
        <div class="item-top">
          <div>
            <h3>${esc(group.name)}</h3>
            <small>${variantText}</small>
          </div>

          <span class="tag">
            ${variants.length>1?'Sizes':esc(variants[0].size||variants[0].unit||'Default')}
          </span>
        </div>

        <div class="variant-list">
          ${variants.map(i=>`
            <button
              type="button"
              class="variant-row ${num(i.stock)<=num(i.min_stock)?'variant-low':''}"
              data-edit-item="${i.id}"
            >
              <div class="variant-heading">
                <strong>${esc(i.size||'Default')}</strong>
                <small>${esc(i.unit||'')}</small>
              </div>

              <div class="variant-prices">
                <span>
                  <small>Sale</small>
                  <b>${money(i.sale_price)}</b>
                </span>

                <span>
                  <small>Purchase</small>
                  <b>${money(i.purchase_price)}</b>
                </span>

                <span>
                  <small>Stock</small>
                  <b class="${num(i.stock)<=num(i.min_stock)?'negative':'positive'}">
                    ${i.stock} ${esc(i.unit||'')}
                  </b>
                </span>
              </div>
            </button>
          `).join('')}
        </div>
      </article>
    `;
  }).join('')||emptyText('No items found');
}

function openItem(item=null){const f=$('#item-form');f.reset();f.elements.id.value=item?.id||'';$('#item-modal-title').textContent=item?'Edit Item':'Add Item';if(item)Object.keys(item).forEach(k=>{if(f.elements[k])f.elements[k].value=item[k]??''});$('#item-dialog').showModal()}
async function saveItem(form){const data=Object.fromEntries(new FormData(form));const id=data.id;delete data.id;['gst_rate','purchase_price','sale_price','mrp','stock','min_stock'].forEach(k=>data[k]=num(data[k]));await api(id?`/api/items/${id}`:'/api/items',{method:id?'PUT':'POST',body:data});$('#item-dialog').close();toast(id?'Item updated':'Item added');await refreshMasterData();renderItems()}

function renderParties(){const q=($('#party-filter').value||'').toLowerCase(),type=$('#party-type-filter').value;const rows=state.parties.filter(p=>(!q||`${p.name} ${p.phone} ${p.gstin}`.toLowerCase().includes(q))&&(!type||p.type===type||p.type==='both'));$('#parties-cards').innerHTML=rows.map(p=>`<article class="party-card"><div class="party-top"><div><h3>${esc(p.name)}</h3><span class="status-pill ${p.type==='supplier'?'purchase':''}">${esc(p.type)}</span></div><button class="icon-button" data-edit-party="${p.id}">${icon('dots')}</button></div><div class="party-values"><div><small>Mobile</small><strong>${esc(p.phone||'-')}</strong></div><div><small>Balance</small><strong class="${num(p.balance)>0?'negative':''}">${money(p.balance)}</strong></div><div><button class="btn secondary" data-ledger="${p.id}">Open Khata</button></div></div></article>`).join('')||emptyText('No parties found')}
function openParty(p=null){const f=$('#party-form');f.reset();f.elements.id.value=p?.id||'';$('#party-modal-title').textContent=p?'Edit Party':'Add Party';if(p)Object.keys(p).forEach(k=>{if(f.elements[k])f.elements[k].value=p[k]??''});$('#party-dialog').showModal()}
async function saveParty(form){const data=Object.fromEntries(new FormData(form));const id=data.id;delete data.id;data.opening_balance=num(data.opening_balance);await api(id?`/api/parties/${id}`:'/api/parties',{method:id?'PUT':'POST',body:data});$('#party-dialog').close();toast(id?'Party updated':'Party added');await refreshMasterData();renderParties()}
async function openLedger(id){const d=await api(`/api/parties/${id}/ledger`);$('#ledger-title').textContent=d.party.name;$('#ledger-summary').innerHTML=`<div><small>Current Balance</small><strong>${money(d.party.balance)}</strong></div><div><small>Type</small><strong>${esc(d.party.type)}</strong></div>`;$('#payment-form').elements.party_id.value=id;$('#payment-form').elements.payment_date.value=today();$('#ledger-list').innerHTML=(d.entries||[]).map(x=>`<div class="simple-row"><div><b>${esc(activityLabel(x.entry_type))}</b><small>${niceDate(x.entry_date)} · ${esc(x.note||'')}</small></div><strong>${money(num(x.debit)||num(x.credit))}</strong></div>`).join('')||emptyText('No ledger entries');$('#ledger-dialog').showModal()}
async function savePayment(form){const data=Object.fromEntries(new FormData(form));data.party_id=Number(data.party_id);data.amount=num(data.amount);await api('/api/payments',{method:'POST',body:data});toast('Payment added');await refreshMasterData();await openLedger(data.party_id)}

function fillPartySelects(){const cust=state.parties.filter(p=>['customer','both'].includes(p.type)),supp=state.parties.filter(p=>['supplier','both'].includes(p.type));$('#sale-party').innerHTML='<option value="">Cash Customer</option>'+cust.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');$('#purchase-party').innerHTML='<option value="">Cash Supplier</option>'+supp.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');['#entry-form [name="party_id"]','#document-form [name="party_id"]'].forEach(sel=>$(sel).innerHTML='<option value="">No Party</option>'+state.parties.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join(''));fillReturnPartySelect();updateSalePartyDetails();updatePurchasePartyDetails();updateReturnPartyDetails()}
function fillEntrySelects(){const opts='<option value="">Default Cash</option>'+state.accounts.map(a=>`<option value="${a.id}">${esc(a.name)} (${money(a.balance)})</option>`).join('');$('#entry-form [name="account_id"]').innerHTML=opts;$('#entry-form [name="to_account_id"]').innerHTML=opts}
function updateSalePartyDetails(){if(!$('#sale-party'))return;const party=state.parties.find(p=>p.id===Number($('#sale-party').value));$('#sale-phone').value=party?.phone||'';$('#sale-party-balance').textContent=money(party?.balance||0);$('#sale-party-balance').className=num(party?.balance)>0?'negative':'positive'}
function updatePurchasePartyDetails(){if(!$('#purchase-party'))return;const party=state.parties.find(p=>p.id===Number($('#purchase-party').value));$('#purchase-phone').value=party?.phone||'';$('#purchase-party-balance').textContent=money(party?.balance||0);$('#purchase-party-balance').className=num(party?.balance)>0?'negative':'positive'}
function fillReturnPartySelect(){if(!$('#return-party'))return;const expected=state.returnKind==='sale_return'?'customer':'supplier',rows=state.parties.filter(p=>[expected,'both'].includes(p.type));const current=$('#return-party').value;$('#return-party').innerHTML=`<option value="">Cash ${expected==='customer'?'Customer':'Supplier'}</option>`+rows.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');if(rows.some(p=>String(p.id)===current))$('#return-party').value=current}
function updateReturnPartyDetails(){if(!$('#return-party'))return;const party=state.parties.find(p=>p.id===Number($('#return-party').value));$('#return-phone').value=party?.phone||'';$('#return-party-balance').textContent=money(party?.balance||0);$('#return-party-balance').className=num(party?.balance)>0?'negative':'positive'}
function updateSaleDueDate(){if(!$('#sale-date')||!$('#sale-due-date'))return;const base=$('#sale-date').value?new Date(`${$('#sale-date').value}T00:00:00`):new Date();base.setDate(base.getDate()+num($('#sale-terms')?.value));$('#sale-due-date').value=base.toISOString().slice(0,10)}
function setSaleType(type,preserveMode=false){state.saleType=type;$('#sale-credit-toggle')?.classList.toggle('active',type==='credit');$('#sale-cash-toggle')?.classList.toggle('active',type==='cash');if(!preserveMode&&$('#sale-mode'))$('#sale-mode').value=type==='credit'?'credit':'cash';if($('#sale-paid'))$('#sale-paid').value=type==='credit'?0:totals(state.saleCart,$('#sale-discount')?.value).total;updateCartTotals('sale')}
function setPurchaseType(type,preserveMode=false){state.purchaseType=type;$('#purchase-credit-toggle')?.classList.toggle('active',type==='credit');$('#purchase-cash-toggle')?.classList.toggle('active',type==='cash');if(!preserveMode&&$('#purchase-mode'))$('#purchase-mode').value=type==='credit'?'credit':'cash';if($('#purchase-paid'))$('#purchase-paid').value=type==='credit'?0:totals(state.purchaseCart,$('#purchase-discount')?.value).total;updateCartTotals('purchase')}
function setReturnKind(kind){state.returnKind=kind;$('#return-sale-toggle')?.classList.toggle('active',kind==='sale_return');$('#return-purchase-toggle')?.classList.toggle('active',kind==='purchase_return');$('#return-page-title').textContent=kind==='sale_return'?'Sale Return':'Purchase Return';$('#return-party-label').textContent=kind==='sale_return'?'Customer':'Supplier';$('#return-paid-label').textContent=kind==='sale_return'?'Refund Paid':'Refund Received';$('#return-due-label').textContent='Credit Adjustment';fillReturnPartySelect();updateReturnPartyDetails();state.returnCart=[];renderCart('return')}

function filteredItems(q){q=q.toLowerCase();return state.items.filter(i=>`${i.name} ${i.sku} ${i.barcode} ${i.size||''}`.toLowerCase().includes(q)).slice(0,12)}
function showItemResults(kind,q){const el=$(`#${kind}-search-results`);if(!q.trim()){el.classList.add('hidden');return}const rows=filteredItems(q),priceKind=kind==='return'?(state.returnKind==='sale_return'?'sale':'purchase'):kind;el.innerHTML=rows.map(i=>`<div class="search-result" data-add-line="${kind}:${i.id}"><div><b>${esc(i.name)}</b><small>${esc(i.sku)}${i.size?` · ${esc(i.size)}`:''} · Stock ${i.stock} ${esc(i.unit||'')}</small></div><strong>${money(priceKind==='sale'?i.sale_price:i.purchase_price)}</strong></div>`).join('')||'<div class="search-result">No item found</div>';el.classList.remove('hidden')}
function addToCart(kind,id){const item=state.items.find(i=>i.id===Number(id));if(!item)return;const cart=state[`${kind}Cart`],found=cart.find(x=>x.item_id===item.id),priceKind=kind==='return'?(state.returnKind==='sale_return'?'sale':'purchase'):kind;if(found)found.qty+=1;else cart.push({item_id:item.id,item_name:item.name,size:item.size||'',qty:1,rate:num(priceKind==='sale'?item.sale_price:item.purchase_price),gst_rate:num(item.gst_rate),unit:item.unit});$(`#${kind}-item-search`).value='';$(`#${kind}-search-results`).classList.add('hidden');renderCart(kind)}
function totals(cart,discount){let subtotal=0,tax=0;cart.forEach(x=>{const base=num(x.qty)*num(x.rate);subtotal+=base;tax+=base*num(x.gst_rate)/100});return{subtotal,tax,total:Math.max(0,subtotal+tax-num(discount))}}
function updateCartTotals(kind){const cart=state[`${kind}Cart`],t=totals(cart,$(`#${kind}-discount`)?.value);if(kind==='sale'&&state.saleType==='cash'&&$(`#${kind}-paid`))$(`#${kind}-paid`).value=t.total;if(kind==='purchase'&&state.purchaseType==='cash'&&$(`#${kind}-paid`))$(`#${kind}-paid`).value=t.total;$(`#${kind}-item-count`).textContent=`${cart.length} item${cart.length===1?'':'s'}`;const copy=$(`#${kind}-item-count-copy`);if(copy)copy.textContent=`${cart.length} item${cart.length===1?'':'s'}`;$(`#${kind}-subtotal`).textContent=money(t.subtotal);$(`#${kind}-tax`).textContent=money(t.tax);$(`#${kind}-total`).textContent=money(t.total);const paid=num($(`#${kind}-paid`).value);$(`#${kind}-due`).textContent=money(Math.max(0,t.total-paid))}
function updateLineWithoutRerender(input){const d=input.dataset.line;if(!d)return;const[k,i,f]=d.split(':'),line=state[`${k}Cart`][Number(i)];if(!line)return;line[f]=f==='size'?input.value:num(input.value);const card=input.closest('.billing-line-card,.sale-line-card');if(card){const base=num(line.qty)*num(line.rate),tax=base*num(line.gst_rate)/100;const totalEl=card.querySelector('[data-line-total]'),amountEl=card.querySelector('[data-line-amount]'),metaEl=card.querySelector('[data-line-meta]');if(totalEl)totalEl.textContent=money(base+tax);if(amountEl)amountEl.textContent=money(base);if(metaEl)metaEl.textContent=`${line.size?`${line.size} · `:''}${line.unit||'pcs'} · GST ${line.gst_rate}%`}updateCartTotals(k)}
function renderCart(kind){const cart=state[`${kind}Cart`],el=$(`#${kind}-cart`);el.innerHTML=cart.map((x,i)=>{const base=num(x.qty)*num(x.rate),tax=base*num(x.gst_rate)/100;return `<article class="billing-line-card ${kind}-line-card"><div class="billing-line-main"><div><span class="line-number">#${i+1}</span><b>${esc(x.item_name)}</b><small data-line-meta>${x.size?`${esc(x.size)} · `:''}${esc(x.unit||'pcs')} · GST ${x.gst_rate}%</small></div><strong data-line-total>${money(base+tax)}</strong></div><div class="billing-line-controls"><label><span>Qty</span><input data-line="${kind}:${i}:qty" inputmode="decimal" type="number" step="0.001" min="0.001" value="${x.qty}"></label><label><span>Size</span><input data-line="${kind}:${i}:size" type="text" value="${esc(x.size||'')}" placeholder="500 gm"></label><label><span>Rate</span><input data-line="${kind}:${i}:rate" inputmode="decimal" type="number" step="0.01" min="0" value="${x.rate}"></label><div><span>Amount</span><b data-line-amount>${money(base)}</b></div><button class="remove-line" data-remove-line="${kind}:${i}" aria-label="Remove item">×</button></div></article>`}).join('');$(`#${kind}-empty`).classList.toggle('hidden',cart.length>0);updateCartTotals(kind)}
function clearCart(kind){state[`${kind}Cart`]=[];$(`#${kind}-discount`).value=0;$(`#${kind}-paid`).value=0;$(`#${kind}-note`).value='';if(kind==='sale'){state.saleType='credit';$('#sale-mode').value='credit';setSaleType('credit')}if(kind==='purchase'){state.purchaseType='credit';$('#purchase-mode').value='credit';$('#purchase-reference').value='';setPurchaseType('credit')}if(kind==='return'){$('#return-reference').value='';$('#return-mode').value='cash'}renderCart(kind)}
async function saveTransaction(kind,options={}){const cart=state[`${kind}Cart`];if(!cart.length)return toast('Pehle item add karein',true);const payload={invoice_no:kind==='purchase'?$('#purchase-reference').value:'',party_id:Number($(`#${kind}-party`).value)||null,invoice_date:$(`#${kind}-date`).value,discount:num($(`#${kind}-discount`).value),paid:num($(`#${kind}-paid`).value),payment_mode:$(`#${kind}-mode`).value,notes:$(`#${kind}-note`).value,items:cart.map(({unit,...x})=>x)};try{const saved=await api(kind==='sale'?'/api/sales':'/api/purchases',{method:'POST',body:payload,queueable:true});clearCart(kind);toast(saved.offline?'Saved offline; will sync later':`${kind==='sale'?'Sale':'Purchase'} saved`);await refreshAll();if(!saved.offline&&options.print)showInvoice(saved,kind);if(options.stay===false)navigate('home');return saved}catch(e){toast(e.message,true)}}
function holdSale(){if(!state.saleCart.length)return toast('Hold karne ke liye item add karein',true);localStorage.setItem('ks_held_sale',JSON.stringify({cart:state.saleCart,party:$('#sale-party').value,discount:$('#sale-discount').value,note:$('#sale-note').value}));$('#restore-sale').classList.remove('hidden');clearCart('sale');toast('Order held')}
function restoreSale(){const raw=localStorage.getItem('ks_held_sale');if(!raw)return;const h=JSON.parse(raw);state.saleCart=h.cart||[];$('#sale-party').value=h.party||'';$('#sale-discount').value=h.discount||0;$('#sale-note').value=h.note||'';renderCart('sale');localStorage.removeItem('ks_held_sale');$('#restore-sale').classList.add('hidden')}
function holdPurchase(){if(!state.purchaseCart.length)return toast('Hold karne ke liye item add karein',true);localStorage.setItem('ks_held_purchase',JSON.stringify({cart:state.purchaseCart,party:$('#purchase-party').value,discount:$('#purchase-discount').value,note:$('#purchase-note').value,reference:$('#purchase-reference').value}));$('#restore-purchase').classList.remove('hidden');clearCart('purchase');toast('Purchase held')}
function restorePurchase(){const raw=localStorage.getItem('ks_held_purchase');if(!raw)return;const h=JSON.parse(raw);state.purchaseCart=h.cart||[];$('#purchase-party').value=h.party||'';$('#purchase-discount').value=h.discount||0;$('#purchase-note').value=h.note||'';$('#purchase-reference').value=h.reference||'';renderCart('purchase');localStorage.removeItem('ks_held_purchase');$('#restore-purchase').classList.add('hidden')}
async function saveReturn(options={}){if(!state.returnCart.length)return toast('Returned item add karein',true);const payload={kind:state.returnKind,reference_no:$('#return-reference').value,party_id:Number($('#return-party').value)||null,return_date:$('#return-date').value,discount:num($('#return-discount').value),paid:num($('#return-paid').value),payment_mode:$('#return-mode').value,notes:$('#return-note').value,items:state.returnCart.map(({unit,...x})=>x)};try{const saved=await api('/api/returns',{method:'POST',body:payload});clearCart('return');toast('Return saved; stock updated');await refreshAll();if(options.print)showInvoice(saved,state.returnKind);return saved}catch(e){toast(e.message,true)}}

async function loadTransactions(){state.activity=await api('/api/activity?limit=300');renderTransactions()}
function renderTransactions(){const q=($('#tx-filter').value||'').toLowerCase();const rows=state.activity.filter(r=>(state.txTab==='all'||(state.txTab==='other'?!['sale','purchase'].includes(r.kind):r.kind===state.txTab))&&`${r.title} ${r.ref} ${r.kind}`.toLowerCase().includes(q));$('#transactions-list').innerHTML=rows.map(r=>`<article class="transaction-card" data-activity-kind="${r.kind}" data-activity-id="${r.id}"><div class="transaction-top"><div><h3>${esc(r.title||activityLabel(r.kind))}</h3><span class="status-pill ${statusClass(r.kind)}">${activityLabel(r.kind)}</span></div><time>${niceDate(r.entry_date)}<br><small>${esc(r.ref||'')}</small></time></div><div class="transaction-values"><div><small>Total</small><strong>${money(r.amount)}</strong></div><div><small>Balance</small><strong>${money(r.due)}</strong></div><div class="transaction-actions">${icon('arrow')}</div></div></article>`).join('')||emptyText('No matching transactions')}

const ENTRY_NAMES={expense:'Expense',cash_in:'Payment-In',cash_out:'Payment-Out',transfer:'P2P Transfer',cheque_received:'Cheque Received',cheque_paid:'Cheque Paid',loan_in:'Loan Received',loan_out:'Loan Payment',asset_purchase:'Asset Purchase',asset_sale:'Asset Sale'};
const DOC_NAMES={sale_return:'Sale Return',purchase_return:'Purchase Return',delivery_challan:'Delivery Challan',estimate:'Estimate / Quotation',proforma:'Proforma Invoice',sale_order:'Sale Order',purchase_order:'Purchase Order',sale_asset:'Sale Asset',purchase_asset:'Purchase Asset'};
function openEntry(type){const f=$('#entry-form');f.reset();f.elements.entry_type.value=type;f.elements.entry_date.value=today();$('#entry-title').textContent=ENTRY_NAMES[type]||'Add Entry';$('#to-account-field').classList.toggle('hidden',type!=='transfer');fillEntrySelects();$('#entry-dialog').showModal()}
async function saveEntry(form){const d=Object.fromEntries(new FormData(form));d.amount=num(d.amount);d.party_id=Number(d.party_id)||null;d.account_id=Number(d.account_id)||null;d.to_account_id=Number(d.to_account_id)||null;await api('/api/entries',{method:'POST',body:d});$('#entry-dialog').close();closeIfOpen($('#txn-launcher'));toast(`${ENTRY_NAMES[d.entry_type]} saved`);await refreshAll();if(state.registerType)openRegister(state.registerType)}
function openDocument(kind){const f=$('#document-form');f.reset();f.elements.kind.value=kind;f.elements.doc_date.value=today();$('#document-title').textContent=DOC_NAMES[kind]||'New Document';fillPartySelects();$('#document-dialog').showModal()}
async function saveDocument(form){const d=Object.fromEntries(new FormData(form));d.amount=num(d.amount);d.party_id=Number(d.party_id)||null;await api('/api/documents',{method:'POST',body:d});$('#document-dialog').close();closeIfOpen($('#txn-launcher'));toast(`${DOC_NAMES[d.kind]} saved`);await loadActivity();if(state.registerType)openRegister(state.registerType)}
async function openRegister(type){state.registerType=type;navigate('register');const title={accounts:'Bank, Cash & Accounts',cheques:'Cheques Register',loans:'Loan Accounts',assets:'Fixed Assets',documents:'Documents & Orders'}[type]||'Register';$('#register-title').textContent=title;$('#register-subtitle').textContent='Complete business register';$('#register-add-btn').textContent=type==='accounts'?'+ Add Account':'+ Add Entry';await loadRegister()}
async function loadRegister(){const type=state.registerType;let rows=[];if(type==='accounts'){rows=await api('/api/accounts');$('#register-summary').innerHTML=`<article class="money-card positive-card"><small>Total Positive</small><strong>${money(rows.filter(x=>x.balance>=0).reduce((a,x)=>a+num(x.balance),0))}</strong></article><article class="money-card negative-card"><small>Total Negative</small><strong>${money(Math.abs(rows.filter(x=>x.balance<0).reduce((a,x)=>a+num(x.balance),0)))}</strong></article>`;$('#register-list').innerHTML=rows.map(r=>`<article class="register-card"><div class="register-top"><div><h3>${esc(r.name)}</h3><span class="status-pill">${esc(r.account_type)}</span></div><strong class="${r.balance>=0?'positive':'negative'}">${money(r.balance)}</strong></div></article>`).join('')||emptyText('No accounts');return}
 if(type==='documents'){rows=await api('/api/documents');$('#register-summary').innerHTML='';$('#register-list').innerHTML=rows.map(r=>registerCard(DOC_NAMES[r.kind]||r.kind,r.doc_no,r.doc_date,r.amount,r.status)).join('')||emptyText('No documents');return}
 const types=type==='cheques'?['cheque_received','cheque_paid']:type==='loans'?['loan_in','loan_out']:['asset_purchase','asset_sale'];rows=await api('/api/entries');rows=rows.filter(x=>types.includes(x.entry_type));$('#register-summary').innerHTML='';$('#register-list').innerHTML=rows.map(r=>registerCard(r.title||ENTRY_NAMES[r.entry_type],ENTRY_NAMES[r.entry_type],r.entry_date,r.amount,r.status)).join('')||emptyText('No entries')}
function registerCard(title,ref,date,amount,status){return `<article class="register-card"><div class="register-top"><div><h3>${esc(title)}</h3><span class="status-pill document">${esc(status||ref)}</span></div><time>${niceDate(date)}<br><small>${esc(ref||'')}</small></time></div><div class="transaction-values"><div><small>Amount</small><strong>${money(amount)}</strong></div></div></article>`}
function addRegister(){if(state.registerType==='accounts')$('#account-dialog').showModal();else if(state.registerType==='cheques')openEntry('cheque_received');else if(state.registerType==='loans')openEntry('loan_in');else if(state.registerType==='assets')openEntry('asset_purchase');else if(state.registerType==='documents')openDocument('estimate')}
async function saveAccount(form){const d=Object.fromEntries(new FormData(form));d.opening_balance=num(d.opening_balance);await api('/api/accounts',{method:'POST',body:d});$('#account-dialog').close();toast('Account added');await refreshMasterData();openRegister('accounts')}

async function viewSale(id){const d=await api(`/api/sales/${id}`);showInvoice(d,'sale')}
async function viewPurchase(id){const d=await api(`/api/purchases/${id}`);showInvoice(d,'purchase')}
async function viewReturn(id){const d=await api(`/api/returns/${id}`);showInvoice(d,d.kind)}
function showInvoice(s,kind='sale'){const b=s.business||state.me?.business||{},isReturn=kind.includes('return'),isPurchase=kind==='purchase'||kind==='purchase_return',docNo=isReturn?s.return_no:s.invoice_no,docDate=isReturn?s.return_date:s.invoice_date,title=kind==='sale'?'TAX INVOICE':kind==='purchase'?'PURCHASE INVOICE':kind==='sale_return'?'SALE RETURN':'PURCHASE RETURN';$('#invoice-sheet').className='invoice-sheet '+($('#invoice-print-size')?.value||'print-a4');$('#invoice-sheet').innerHTML=`<div class="invoice-top"><div><h2>${esc(b.name||'Kirana Software')}</h2><p>${esc(b.address||'')}</p><p>${esc(b.phone||'')} ${b.gstin?`· GSTIN ${esc(b.gstin)}`:''}</p></div><div class="invoice-meta"><b>${title}</b><p>${esc(docNo||'')}</p><p>${niceDate(docDate)}</p>${s.reference_no?`<p>Ref: ${esc(s.reference_no)}</p>`:''}</div></div><div class="invoice-party"><b>${isPurchase?'Supplier':'Bill To'}:</b> ${esc(s.party_name||(isPurchase?'Cash Supplier':'Cash Customer'))}</div><table class="invoice-table"><thead><tr><th>Item</th><th>Size</th><th>Qty</th><th>Rate</th><th>Total</th></tr></thead><tbody>${(s.items||[]).map(x=>`<tr><td>${esc(x.item_name)}</td><td>${esc(x.size||'-')}</td><td>${x.qty}</td><td>${money(x.rate)}</td><td>${money(x.line_total)}</td></tr>`).join('')}</tbody></table><div class="invoice-totals"><div><span>Subtotal</span><b>${money(s.subtotal)}</b></div><div><span>Discount</span><b>${money(s.discount)}</b></div><div><span>Tax</span><b>${money(s.tax)}</b></div><div><span>Grand Total</span><b>${money(s.total)}</b></div><div><span>${isReturn?'Settled':'Paid'}</span><b>${money(s.paid)}</b></div><div><span>${isReturn?'Credit Adj.':'Balance'}</span><b>${money(s.due)}</b></div></div><p class="invoice-thanks">${isReturn?'Goods return acknowledgement':'Thank you for shopping with us.'}</p>`;$('#invoice-dialog').showModal()}

async function previewImport(doImport=false){const file=$('#import-file').files[0];if(!file)return toast('File choose karein',true);const fd=new FormData();fd.append('file',file);fd.append('entity_type',$('#import-type').value);fd.append('dry_run',doImport?'false':'true');try{const r=await api('/api/import/vyapar',{method:'POST',body:fd});$('#import-result').classList.remove('hidden');$('#import-result').innerHTML=`<b>${doImport?'Import completed':'Preview ready'}</b><div class="simple-row"><span>Total rows</span><strong>${r.rows_total??r.preview?.length??0}</strong></div><div class="simple-row"><span>Imported</span><strong>${r.rows_imported??0}</strong></div>${r.preview?`<pre>${esc(JSON.stringify(r.preview.slice(0,8),null,2))}</pre>`:''}`;if(doImport){await refreshAll();loadImportHistory()}}catch(e){toast(e.message,true)}}
async function loadImportHistory(){const rows=await api('/api/import/batches');$('#import-history').innerHTML=rows.map(r=>`<div class="simple-row"><div><b>${esc(r.entity_type)} · ${esc(r.filename)}</b><small>${niceDate(r.created_at?.slice(0,10))}</small></div><strong>${r.rows_imported}/${r.rows_total}</strong></div>`).join('')||emptyText('Abhi koi import nahi hua.')}
async function loadReports(){const from=$('#report-from').value||new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10),to=$('#report-to').value||today();$('#report-from').value=from;$('#report-to').value=to;const r=await api(`/api/reports/summary?date_from=${from}&date_to=${to}`);const cards=[['Net Sales',r.net_sales??r.sales.amount,`${r.sales.count} bills · returns ${money(r.sale_returns?.amount)}`],['Net Purchase',r.net_purchases??r.purchases.amount,`${r.purchases.count} entries · returns ${money(r.purchase_returns?.amount)}`],['Stock Value',r.stock_value,'At purchase rate'],['Total Tax',num(r.sales.tax)+num(r.purchases.tax)-num(r.sale_returns?.tax)-num(r.purchase_returns?.tax),'Net tax movement']];$('#report-cards').innerHTML=cards.map(c=>`<div class="report-stat"><small>${c[0]}</small><strong>${money(c[1])}</strong><small>${c[2]}</small></div>`).join('');$('#top-items').innerHTML=(r.top_items||[]).map(x=>`<div class="simple-row"><div><b>${esc(x.item_name)}${x.size?` · ${esc(x.size)}`:''}</b><small>${x.qty} qty</small></div><strong>${money(x.amount)}</strong></div>`).join('')||emptyText('No sale data');$('#margin-number').textContent=money(r.gross_margin_estimate)}
function fillBusinessForm(){if(!state.me)return;const f=$('#business-form'),b=state.me.business;Object.keys(b).forEach(k=>{if(f.elements[k])f.elements[k].value=b[k]??''})}
async function saveBusiness(form){const d=Object.fromEntries(new FormData(form));state.me.business=await api('/api/business',{method:'PUT',body:d});$('#shop-name').textContent=d.name;$('#drawer-shop').textContent=d.name;toast('Business settings saved')}
async function downloadProtected(path,filename){try{const r=await fetch(path,{headers:{Authorization:`Bearer ${state.token}`}});if(!r.ok){const d=await r.json().catch(()=>null);throw new Error(d?.detail||'Download failed')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(`${filename} downloaded`)}catch(e){toast(e.message,true)}}
function emptyText(t){return `<div style="padding:28px;text-align:center;color:var(--muted)">${esc(t)}</div>`}

function attachEvents(){
  window.addEventListener('online',()=>{updateSyncUI();flushQueue()});window.addEventListener('offline',updateSyncUI);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredPrompt=e;$('#install-btn').classList.remove('hidden')});
  document.addEventListener('click',async e=>{const go=e.target.closest('[data-go]');if(go){const page=go.dataset.go;if(page==='sale'||page==='purchase'){closeIfOpen($('#txn-launcher'))}navigate(page);return}if(e.target.closest('#desktop-menu-btn')||e.target.closest('#profile-btn'))return openDrawer();if(e.target.closest('#drawer-backdrop'))return closeDrawer();if(e.target.closest('.close-modal'))return e.target.closest('dialog').close();const act=e.target.closest('[data-action]');if(act?.dataset.action==='new-item')return openItem();if(act?.dataset.action==='new-party')return openParty();const editItem=e.target.closest('[data-edit-item]');if(editItem)return openItem(state.items.find(i=>i.id===Number(editItem.dataset.editItem)));const editParty=e.target.closest('[data-edit-party]');if(editParty)return openParty(state.parties.find(p=>p.id===Number(editParty.dataset.editParty)));const led=e.target.closest('[data-ledger]');if(led)return openLedger(Number(led.dataset.ledger));const add=e.target.closest('[data-add-line]');if(add){const [k,id]=add.dataset.addLine.split(':');return addToCart(k,id)}const rem=e.target.closest('[data-remove-line]');if(rem){const[k,i]=rem.dataset.removeLine.split(':');state[`${k}Cart`].splice(Number(i),1);return renderCart(k)}const entry=e.target.closest('[data-entry-type]');if(entry){closeIfOpen($('#txn-launcher'));return openEntry(entry.dataset.entryType)}const ret=e.target.closest('[data-open-return]');if(ret){closeIfOpen($('#txn-launcher'));setReturnKind(ret.dataset.openReturn);navigate('return');return}const doc=e.target.closest('[data-document-kind]');if(doc){closeIfOpen($('#txn-launcher'));return openDocument(doc.dataset.documentKind)}const reg=e.target.closest('[data-register]');if(reg)return openRegister(reg.dataset.register);if(e.target.closest('#register-add-btn'))return addRegister();const menuLaunch=e.target.closest('[data-menu-launch]');if(menuLaunch)return $('#txn-launcher').showModal();const txTab=e.target.closest('[data-tx-tab]');if(txTab){state.txTab=txTab.dataset.txTab;$$('[data-tx-tab]').forEach(b=>b.classList.toggle('active',b===txTab));return renderTransactions()}const card=e.target.closest('[data-activity-kind]');if(card){const kind=card.dataset.activityKind,id=Number(card.dataset.activityId);if(kind==='sale')return viewSale(id);if(kind==='purchase')return viewPurchase(id);if(['sale_return','purchase_return'].includes(kind))return viewReturn(id)}});
  $('#setup-form').addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('/api/setup',{method:'POST',body:Object.fromEntries(new FormData(e.target))});state.token=r.token;localStorage.setItem('ks_token',state.token);await enterApp()}catch(err){toast(err.message,true)}});
  $('#login-form').addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('/api/login',{method:'POST',body:Object.fromEntries(new FormData(e.target))});state.token=r.token;localStorage.setItem('ks_token',state.token);await enterApp()}catch(err){toast(err.message,true)}});
  $('#logout-btn').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST'})}catch{}logoutLocal()});$('#settings-logout').addEventListener('click',()=>$('#logout-btn').click());
  $('#open-txn-launcher').addEventListener('click',()=>$('#txn-launcher').showModal());$('#open-txn-launcher-2').addEventListener('click',()=>$('#txn-launcher').showModal());
  $('#item-form').addEventListener('submit',e=>{e.preventDefault();saveItem(e.target).catch(x=>toast(x.message,true))});$('#party-form').addEventListener('submit',e=>{e.preventDefault();saveParty(e.target).catch(x=>toast(x.message,true))});$('#payment-form').addEventListener('submit',e=>{e.preventDefault();savePayment(e.target).catch(x=>toast(x.message,true))});$('#entry-form').addEventListener('submit',e=>{e.preventDefault();saveEntry(e.target).catch(x=>toast(x.message,true))});$('#document-form').addEventListener('submit',e=>{e.preventDefault();saveDocument(e.target).catch(x=>toast(x.message,true))});$('#account-form').addEventListener('submit',e=>{e.preventDefault();saveAccount(e.target).catch(x=>toast(x.message,true))});
  $('#sale-item-search').addEventListener('input',e=>showItemResults('sale',e.target.value));$('#purchase-item-search').addEventListener('input',e=>showItemResults('purchase',e.target.value));$('#return-item-search').addEventListener('input',e=>showItemResults('return',e.target.value));['sale','purchase','return'].forEach(k=>{['discount','paid'].forEach(f=>$(`#${k}-${f}`).addEventListener('input',()=>updateCartTotals(k)))});$('#sale-party').addEventListener('change',updateSalePartyDetails);$('#purchase-party').addEventListener('change',updatePurchasePartyDetails);$('#return-party').addEventListener('change',updateReturnPartyDetails);$('#sale-date').addEventListener('change',updateSaleDueDate);$('#sale-terms').addEventListener('change',updateSaleDueDate);$('#sale-credit-toggle').addEventListener('click',()=>setSaleType('credit'));$('#sale-cash-toggle').addEventListener('click',()=>setSaleType('cash'));$('#sale-mode').addEventListener('change',e=>setSaleType(e.target.value==='credit'?'credit':'cash',true));$('#purchase-credit-toggle').addEventListener('click',()=>setPurchaseType('credit'));$('#purchase-cash-toggle').addEventListener('click',()=>setPurchaseType('cash'));$('#purchase-mode').addEventListener('change',e=>setPurchaseType(e.target.value==='credit'?'credit':'cash',true));$('#return-sale-toggle').addEventListener('click',()=>setReturnKind('sale_return'));$('#return-purchase-toggle').addEventListener('click',()=>setReturnKind('purchase_return'));document.addEventListener('input',e=>{if(e.target.dataset.line)updateLineWithoutRerender(e.target)});
  $('#save-sale').addEventListener('click',()=>saveTransaction('sale',{print:true}));$('#save-sale-new').addEventListener('click',()=>saveTransaction('sale',{print:false}));$('#save-purchase').addEventListener('click',()=>saveTransaction('purchase',{print:true}));$('#save-purchase-new').addEventListener('click',()=>saveTransaction('purchase',{print:false}));$('#save-return').addEventListener('click',()=>saveReturn({print:true}));$('#save-return-new').addEventListener('click',()=>saveReturn({print:false}));$('#clear-sale').addEventListener('click',()=>{if(state.saleCart.length&&!confirm('Current bill clear karein?'))return;clearCart('sale')});$('#clear-purchase').addEventListener('click',()=>{if(state.purchaseCart.length&&!confirm('Current purchase clear karein?'))return;clearCart('purchase')});$('#clear-return').addEventListener('click',()=>clearCart('return'));$('#hold-sale').addEventListener('click',holdSale);$('#restore-sale').addEventListener('click',restoreSale);$('#hold-purchase').addEventListener('click',holdPurchase);$('#restore-purchase').addEventListener('click',restorePurchase);
  $('#item-filter').addEventListener('input',renderItems);$('#low-stock-btn').addEventListener('click',e=>{e.currentTarget.classList.toggle('active-filter');renderItems()});$('#party-filter').addEventListener('input',renderParties);$('#party-type-filter').addEventListener('change',renderParties);$('#activity-search').addEventListener('input',renderActivity);$('#tx-filter').addEventListener('input',renderTransactions);
  $('#import-file').addEventListener('change',e=>$('#chosen-file').textContent=e.target.files[0]?.name||'');$('#preview-import').addEventListener('click',()=>previewImport(false));$('#import-form').addEventListener('submit',e=>{e.preventDefault();previewImport(true)});$('#load-report').addEventListener('click',loadReports);$('#business-form').addEventListener('submit',e=>{e.preventDefault();saveBusiness(e.target).catch(x=>toast(x.message,true))});$('#manual-sync').addEventListener('click',flushQueue);$('#print-invoice').addEventListener('click',()=>window.print());$('#invoice-print-size').addEventListener('change',e=>{$('#invoice-sheet').className=`invoice-sheet ${e.target.value}`});$('#export-items').addEventListener('click',()=>downloadProtected('/api/export/items.csv','kirana-items.csv'));$('#export-parties').addEventListener('click',()=>downloadProtected('/api/export/parties.csv','kirana-parties.csv'));$('#export-sales').addEventListener('click',()=>downloadProtected('/api/export/sales.csv','kirana-sales.csv'));$('#export-purchases').addEventListener('click',()=>downloadProtected('/api/export/purchases.csv','kirana-purchases.csv'));$('#backup-db').addEventListener('click',()=>downloadProtected('/api/backup/database',`kirana-backup-${today()}.db`));
  $('#install-btn').addEventListener('click',async()=>{if(state.deferredPrompt){state.deferredPrompt.prompt();await state.deferredPrompt.userChoice;state.deferredPrompt=null;$('#install-btn').classList.add('hidden')}});
  $('#sale-date').value=$('#purchase-date').value=$('#return-date').value=today();$('#sale-time').textContent=$('#purchase-time').textContent=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});updateSaleDueDate();setSaleType('credit');setPurchaseType('credit');setReturnKind('sale_return');$('#report-from').value=new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10);$('#report-to').value=today();$('#restore-sale').classList.toggle('hidden',!localStorage.getItem('ks_held_sale'));$('#restore-purchase').classList.toggle('hidden',!localStorage.getItem('ks_held_purchase'));
}

boot();
